pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface LogFileLike {
    function History(uint256) external view returns (address, string memory, uint256, uint256);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address logAddr, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(uint256(uint160(logAddr)) > 100); // avoid precompiles/special addresses
        amount = bound(amount, 1, 10 ether);

        vm.prank(actor);
        c.SetLogFile(logAddr);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        LogFileLike log = LogFileLike(logAddr);
        (address sender, , uint256 val, ) = log.History(0);
        assertTrue(sender == actor && val == amount,
            "Deposit must be recorded in the log address set via SetLogFile");
    }
}

