pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // Adversarial environment: a live LogFile the contract can be pointed at.
        LiveLog log = new LiveLog();

        // Drive c through SetLogFile: point it at our live log (not yet initialized, so no revert).
        c.SetLogFile(address(log));

        // Deposit through the (fuzzed) actor; the reference logs to the configured LogFile and succeeds.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after a successful SetLogFile to a live LogFile, any Deposit succeeds.
        assertTrue(ok);
    }
}

// Minimal live LogFile accepting AddMessage, so the configured log has code.
contract LiveLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        History.push(Message(_adr, _val, _data, block.timestamp));
    }
}

