pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < 1 ether);
        vm.assume(actor != address(0) && actor.code.length == 0);

        // c's configured log target: a contract that records AddMessage calls
        Logger logger = new Logger();

        // configure the log destination from a DIFFERENT actor than the log
        vm.prank(actor);
        c.SetLogFile(address(logger));

        // deposit from that actor; c must log it at the address given to SetLogFile
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // the deposit must have been recorded at the configured log address
        assertTrue(
            logger.count() > 0
            && logger.senders(logger.count() - 1) == actor
            && logger.vals(logger.count() - 1) == amount,
            "Deposit must be logged at the address passed to SetLogFile"
        );
    }
}

contract Logger {
    address[] public senders;
    uint256[] public vals;

    function AddMessage(address _adr, uint256 _val, string calldata) external {
        senders.push(_adr);
        vals.push(_val);
    }

    function count() external view returns (uint256) {
        return senders.length;
    }
}

