contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint _val) public {
        require(_val > 0);
        bool okBefore;
        // On P: not yet initialized, so SetMinSum succeeds and updates MinSum.
        c.SetMinSum(_val);
        okBefore = (c.MinSum() == _val);
        // After initializing, SetMinSum must revert (unobservable success would break P too).
        bool reverted;
        c.Initialized();
        (bool success,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val + 1));
        reverted = !success;
        assert(okBefore && reverted);
    }
    receive() external payable {}
    fallback() external payable {}
}

